"use client";

import { Grid, GridColProps } from '@mantine/core';
import classes from '@/components/rendyn-libraries/mantine/upstream/src/demos/core/Grid/_col-wrapper.module.css';

export function ColWrapper({ children, ...others }: GridColProps) {
  return (
    <Grid.Col {...others}>
      <div className={classes.col}>
        <div className={classes.label}>{children}</div>
      </div>
    </Grid.Col>
  );
}

.col {
  height: 100%;
  background-color: light-dark(var(--mantine-color-blue-0), var(--mantine-color-dark-4));
  padding: var(--mantine-spacing-md);
}

.label {
  color: light-dark(var(--mantine-color-blue-6), var(--mantine-color-dimmed));
  font-size: var(--mantine-font-size-xl);
  font-weight: bold;
  text-align: center;
  height: 100%;
}

